import {mapGetters} from "vuex";
import { getDictList } from '@/api/dict'
import { add, edit } from "@/api/xcnanr/room"

export default {
  props: ['isShow', 'operatorType', 'formDetial'],
  components:{ getDictList },
  data() {
    return {
      pickerOptions: {
        disabledDate: (time) => {
          return time.getTime() < new Date()
        }
      },
      roomTypeList:[],
      saveLoading: false,
      loading: false,
      rules: {
        companyName: [
          {required: true, message: '授权公司不能为空', trigger: 'blur'},
        ],
        type: [
          {required: true, message: '机房类型不能为空', trigger: 'blur'},
        ],
        name: [
          {required: true, message: '机房名称不能为空', trigger: 'blur'},
        ]
      },
      dialogType: null, dialogFlag: false,
      isUploading: false,
      baseImage: null
    };
  },
  computed: {
    ...mapGetters(["userDetail"]),
  },
  created(){
    this.getList();
    this.getDictList('info_room_type')
  },
  mounted() {
    this.$nextTick(() => {
      this.$refs.submitForm.$forceUpdate()
      this.$forceUpdate()
    });
  },
  methods: {
    // 加载字典
    getDictList(code){
      getDictList(code).then(res => {
        if(code==='info_room_type'){
          this.roomTypeList = res.data
        }
      })
    },
    // 字典回显
    conversionDict(code, dictList) {
      if (dictList != null && code !== '') {
        let items = dictList.filter(item => item.dictKey == code)
        if (items != null && items.length > 0) {
          return items[0].dictValue
        }
      }
      return code
    },
    submit() {
      this.$refs.submitForm.validate((valid) => {
        if (valid) {
          this.saveLoading = true
          if (this.operatorType === 'add') {
            add(this.formDetial).then(() => {
              this.$message({
                type: "success",
                message: "新增成功!"
              });
              this.$emit('refreshData');
              this.$emit('close');
            }).catch(err => {
              console.log(err)
            }).finally(() => {
              this.saveLoading = false
            });
          } else {
            edit(this.formDetial).then(() => {
              this.$message({
                type: "success",
                message: "更新成功!"
              });
              this.$emit('refreshData');
              this.$emit('close');
            }).catch(err => {
              console.log(err)
            }).finally(() => {
              this.saveLoading = false
            });
          }
        }
      })
    },
    getList() {
      if (this.operatorType === 'add'){
        this.formDetial = {
          companyId: this.userDetail.ownerUnit,
          companyName: this.userDetail.ownerUnitName,
          type: '1'
        }
      }
    },
    getTitle(type) {
      if (type === 'add') {
        return '新 增';
      } else if (type === 'edit') {
        return '编 辑';
      }
      return null;
    }
  }
}
